create or replace function public.ateek_profile_by_username(p_username text) returns table(id uuid,name text,username text,verified boolean,bio text,avatar_url text,cover_url text,badge_label text,is_founder boolean,last_seen_at timestamptz,followers bigint,following bigint,completed_deals bigint,avg_rating numeric,reviews_count bigint,response_seconds_avg bigint) language sql stable security definer set search_path=public as $$ select p.id,p.name,p.username,p.verified,p.bio,p.avatar_url,p.cover_url,p.badge_label,p.is_founder,case when coalesce(p.activity_visible,true) then p.last_seen_at else null end,(select count(*) from public.ateek_follows f where f.followed_id=p.id),(select count(*) from public.ateek_follows f where f.follower_id=p.id),(select count(*) from public.ateek_offers o join public.ateek_threads t on t.id=o.thread_id where o.status='completed' and p.id in(t.buyer_id,t.seller_id)),coalesce((select round(avg(r.stars)::numeric,2) from public.ateek_reviews r where r.target_id=p.id),0),(select count(*) from public.ateek_reviews r where r.target_id=p.id),case when p.response_count>0 then(p.response_seconds_total/p.response_count)::bigint else 0 end from public.ateek_profiles p where lower(p.username)=lower(trim(p_username)) limit 1; $$;
